test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 8500 + 3 * 9500;
  const discount1 = (5 * 8500 * 10) / 100;
  const discount2 = (3 * 9500 * 20) / 100;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount1 + discount2);
  assert.equal(totals.total, subtotal - (discount1 + discount2));
});

