test('issueInvoice preserves all invoice data', () => {
  const invoice = {
    customerId: 'C-005',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };

  const result = issueInvoice(invoice, ['INV-2026-0001', 'INV-2026-0002']);
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-005');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.number, 'INV-2026-0003');
  assert.equal(result.value.lines.length, 2);
  assert.deepEqual(result.value.lines[0], { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 });
  assert.deepEqual(result.value.lines[1], { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 });
});
